<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';
require_once __DIR__ . '/../modules/affiliates.php';
require_once __DIR__ . '/../modules/integrations.php';
require_login();
$affiliates = affiliate_read_all();
$salesTotal = array_sum(array_column($affiliates, 'sales'));
$ordersTotal = array_sum(array_column($affiliates, 'orders'));
$commissionTotal = array_sum(array_map(static fn($a) => (float)$a['sales'] * (float)$a['commission'] / 100, $affiliates));
$orderStmt=app_db()->prepare('SELECT o.external_order_id,o.external_product_id,o.product_name,o.affiliate_code,o.amount_cents,o.commission_cents,o.status,o.sold_at,c.name AS connection_name,a.name AS affiliate_name FROM sales_orders o JOIN integration_connections c ON c.id=o.connection_id LEFT JOIN affiliates a ON a.id=o.affiliate_id AND a.tenant_id=o.tenant_id WHERE o.tenant_id=? ORDER BY o.sold_at DESC LIMIT 50');$orderStmt->execute([tenant_id()]);$integratedOrders=$orderStmt->fetchAll();
$kiwifySummary=app_db()->prepare("SELECT COUNT(*) AS orders,COALESCE(SUM(CASE WHEN status='approved' THEN amount_cents ELSE 0 END),0) AS approved_cents,COALESCE(SUM(CASE WHEN status='refunded' THEN amount_cents ELSE 0 END),0) AS refunded_cents FROM sales_orders WHERE tenant_id=?");$kiwifySummary->execute([tenant_id()]);$kiwifyStats=$kiwifySummary->fetch();
$search = trim((string)($_GET['q'] ?? ''));
$groupFilter = (string)($_GET['group'] ?? 'all');
$statusFilter = (string)($_GET['status'] ?? 'all');
$groups = array_values(array_unique(array_map(static fn($a) => (string)$a['group'], $affiliates)));
$rows = array_values(array_filter($affiliates, static function($a) use($search,$groupFilter,$statusFilter){
    $matches = $search === '' || stripos($a['name'].' '.$a['email'].' '.$a['code'], $search) !== false;
    return $matches && ($groupFilter === 'all' || $a['group'] === $groupFilter) && ($statusFilter === 'all' || $a['status'] === $statusFilter);
}));
usort($rows, static fn($a,$b) => (float)$b['sales'] <=> (float)$a['sales']);
$money = static fn($v) => 'R$ '.number_format((float)$v,2,',','.');
function se($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vendas — AFFILIEY</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/sales.css"><link rel="stylesheet" href="assets/css/sales-integrations.css"><script src="assets/js/sales.js" defer></script><link rel="stylesheet" href="assets/css/app-theme.css?v=3"><link rel="manifest" href="/manifest.webmanifest"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="default"><link rel="apple-touch-icon" sizes="180x180" href="/brand/affiliey-apple-touch-icon.png"><link rel="stylesheet" href="/assets/css/pwa.css"><script src="/assets/js/pwa.js" defer></script><link rel="icon" type="image/png" href="/brand/affiliey-favicon.png"><link rel="stylesheet" href="/assets/css/brand.css?v=affiliey4"><link rel="stylesheet" href="/assets/css/workspace-premium.css?v=1"><link rel="stylesheet" href="/assets/css/sliding-pill-nav.css?v=2"><script src="/assets/js/sliding-pill-nav.js?v=1" defer></script><meta name="theme-color" content="#111827"><meta property="og:site_name" content="AFFILIEY"><meta name="description" content="Gestão de afiliados, vendas, metas e campanhas em uma plataforma."><meta property="og:description" content="Gestão de afiliados, vendas, metas e campanhas em uma plataforma."><meta property="og:type" content="website"><meta property="og:title" content="AFFILIEY | Plataforma de afiliados"><meta property="og:image" content="https://afiliados.horizoncafe.com.br/brand/affiliey-logo-light.png"><link rel="stylesheet" href="/assets/css/page-transitions.css?v=2"><script src="/assets/js/page-transitions.js?v=2" defer></script><link rel="stylesheet" href="/assets/css/typography.css?v=1"></head><body class="app-shell">
